const awkward = {
  name: 'Gäste — SSID «offen»',
  summary: 'Line one.\nLine two will utilise the SSID.\n\n  Indented, and spaced.  ',
  preconditions: '日本語のテキスト - and an em dash — here.',
}

/** The same content with nothing for these Rules to fire on. */
