async function submit(testCase: TestCase) {
  const testlink = new StubTestLinkClient()
  testlink.holdSuite('48')
  const app = buildApp({ documents: new StubDocumentStore(), testlink, rules })

  return app.inject({
    method: 'POST',
    url: '/projects/12/suites/48/test-cases',
    payload: testCase,
  })
}

