import { describe, expect, it } from 'vitest'

import { buildApp } from '../src/app.js'
import { PostgresStore } from '../src/postgres-store.js'
import type { Queries } from '../src/queries.js'
import { empty, shipped } from './shipped.js'
import { StubTestLinkClient } from './stub-testlink-client.js'

/** The schema the repository ships, which is the operator's first step. */
const schema = shipped('schema.sql')

/** The columns an operator names to write a Rule, in the order the values follow. */
const writeRule =
  'insert into rules (rule_id, content_kind, field, category, looks_for, flanked, reason) values ($1, $2, $3, $4, $5, $6, $7)'

/** One Rule, written the way an operator writes one. */
const noUtilise = [
  'no-utilise',
  'testCase',
  'summary',
  'term',
  'utilise',
  null,
  'The product documentation says use, not utilise.',
]

/**
 * A database an operator has written their Rules and Reference Documents into,
 * as a running server would find one. The writes are plain SQL because that is
 * now the whole of the write path: nothing this project ships puts a row in this
 * database.
 */
async function configured(): Promise<{ queries: Queries; store: PostgresStore }> {
  const queries = empty()

  await queries.run(schema)
  await queries.run(writeRule, noUtilise)
  await queries.run('insert into reference_documents (id, title, body) values ($1, $2, $3)', [
    'roaming',
    'Roaming between APs',
    'The client reconnects.',
  ])
  await queries.run('insert into reference_documents (id, title, body) values ($1, $2, $3)', [
    'ssid',
    'SSID naming',
    'Name it well.',
  ])

  return { queries, store: new PostgresStore(queries) }
}

describe('the schema the repository ships', () => {
...
 *
 * The statements are the ones the README documents, extracted rather than
 * restated. ADR-0006 answers ADR-0005's objection to writing Rules out of band
 * by pointing at documented SQL — so this fails if that documentation drifts
 * into statements a Postgres will not run, or writes something the server then
 * cannot read.
 *
 * It runs every ```sql block in the README, in order, as one setup. That is the
 * point — the README is a sequence an operator follows top to bottom — but it
 * means a block added there joins this fixture, and the expectations below are
 * pinned to what those blocks write: the id `roaming`, its title, and a document
 * breaking none of the Rules the same README writes. A block that changes any of
 * those fails here, which is the reminder to update both together. Statements
 * shown for reference rather than to be run are fenced without a language, and
 * so are left out.
 */
describe('from the SQL an operator writes to what a caller reads', () => {
  /** Every ```sql block in the README, in the order it documents them. */
  function documentedSql(): string[] {
    return [...shipped('README.md').matchAll(/```sql\n([\s\S]*?)```/g)].map(([, sql]) => sql)
  }

  async function running() {
    const queries = empty()

    await queries.run(schema)

    for (const sql of documentedSql()) {
      await queries.run(sql)
    }

    const store = new PostgresStore(queries)

    // A Suite to write into, so a submission the Rules pass reaches a write
    // rather than stopping at a TestLink holding nothing.
    const testlink = new StubTestLinkClient()
    testlink.holdSuite('48')

    return buildApp({
      testlink,
      documents: store,
      // Exactly what the server does at startup: bind what the database holds.
      rules: await store.rules(),
    })
  }

  it('serves what was written, under the id it was written under', async () => {
    const app = await running()

    const listed = await app.inject({ method: 'GET', url: '/reference-documents' })

    expect(listed.statusCode).toBe(200)
    expect(listed.json()).toEqual([{ id: 'roaming', title: 'Roaming between access points' }])
  })

  it('retrieves a document by the id the listing gave, and nothing else', async () => {
    const app = await running()

    const [{ id }] = (await app.inject({ method: 'GET', url: '/reference-documents' })).json() as {
      id: string
    }[]
    const retrieved = await app.inject({ method: 'GET', url: `/reference-documents/${id}` })

    expect(retrieved.statusCode).toBe(200)
    expect(retrieved.json().document.title).toBe('Roaming between access points')
  })

  it('runs the Rules that were written beside it, finding nothing in the documented example', async () => {
    const app = await running()

    const response = await app.inject({ method: 'GET', url: '/reference-documents/roaming' })

    expect(response.json().violations).toEqual([])
    expect(response.json().ruleSetVersion).toEqual(expect.any(String))
  })

  // The Rules that reached the server came out of the database, so this fails if
  // what was written is not what is being enforced.
  it('rejects a Test Case under the Rules that were written, not under none', async () => {
    const app = await running()

    const response = await app.inject({
      method: 'POST',
      url: '/projects/12/suites/48/test-cases',
      payload: { name: 'Verify that the client roams', summary: 'The client reconnects.' },
    })

    expect(response.statusCode).toBe(422)
    expect(response.json().violations).toEqual([
      expect.objectContaining({ field: 'name', rule: 'no-verify-that' }),
    ])
